const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F\u2080(1 \u2212 x/h)' },
      { kind: 'text', payload: 'F(x)' },
      { kind: 'text', payload: 'F\u2080' },
      { kind: 'text', payload: 'F\u2080/2' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'W = 3/8 F\u2080h = 0.375 F\u2080h' },
      { kind: 'text', payload: 'W' }
    ];
  },
  render: function (input, metrics) {
    var VW = input.viewport.widthDu;
    var VH = input.viewport.heightDu;
    var left = VW * 0.14;
    var right = VW * 0.92;
    var top = VH * 0.16;
    var bottom = VH * 0.78;
    var pw = right - left;
    var ph = bottom - top;

    function X(u) { return left + u * pw; }
    function Y(v) { return bottom - v * ph; }

    var shade = [
      ['M', X(0), Y(0)],
      ['L', X(0), Y(1)],
      ['L', X(0.5), Y(0.5)],
      ['L', X(0.5), Y(0)],
      ['Z']
    ];

    var vguide = [
      ['M', X(0.5), Y(0)],
      ['L', X(0.5), Y(0.5)]
    ];

    var hguide = [
      ['M', left, Y(0.5)],
      ['L', X(0.5), Y(0.5)]
    ];

    var xaxis = visualSdk.arrow(left - 24, bottom, right, bottom, {});
    var yaxis = visualSdk.arrow(left, bottom, left, top, {});
    var curve = visualSdk.polyline([[X(0), Y(1)], [X(1), Y(0)]]);

    return {
      schemaVersion: 1,
      sceneId: 'f0-linear-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: VW, height: VH },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'vguide', commands: vguide },
        { id: 'hguide', commands: hguide },
        { id: 'xaxis', commands: xaxis },
        { id: 'yaxis', commands: yaxis },
        { id: 'curve', commands: curve }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'shade', fill: '#2C7BE533' },
          { type: 'path', pathId: 'vguide', fill: '#7A8B99', stroke: { width: 1.4, dash: [5, 4] } },
          { type: 'path', pathId: 'hguide', fill: '#7A8B99', stroke: { width: 1.4, dash: [5, 4] } },
          { type: 'path', pathId: 'xaxis', fill: '#26354A', stroke: { width: 2, cap: 'butt' } },
          { type: 'path', pathId: 'yaxis', fill: '#26354A', stroke: { width: 2, cap: 'butt' } },
          { type: 'path', pathId: 'curve', fill: '#B03A2E', stroke: { width: 2.6, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: right, y: top - 6 }, hAlign: 'right', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: left, y: top - 22 }, hAlign: 'center', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: left - 10, y: Y(1) }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: left - 10, y: Y(0.5) }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: left - 10, y: Y(0) }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: X(0.5), y: Y(0) + 10 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: X(1), y: Y(0) + 10 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: right + 12, y: Y(0) }, hAlign: 'left', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: right - 4, y: Y(0.88) }, hAlign: 'right', vAlign: 'middle', color: '#1F4E79' },
          { type: 'label', contentId: metrics[9].contentId, anchor: { x: X(0.2), y: Y(0.36) }, hAlign: 'center', vAlign: 'middle', color: '#1B4F8A' }
        ]
      }
    };
  }
};
